// GET /api/v1/health only reports { ai_engine: 'up'|'down' } (no round-trip
// timing field) — this measures wall-clock latency of that same call
// client-side so the "Real-Time Latency" stat pod still reflects something
// genuinely live rather than a fabricated number.
async function getHealthWithLatency() {
  const start = performance.now();
  const health = await getHealth();
  return { ...health, latencyMs: Math.round(performance.now() - start) };
}

